/// <summary>
/// extension of FDS smmActivities
/// </summary>
[ExtensionOf(FormDatasourceStr(smmActivities, smmActivities))]
final class AVAsmmActivitiesFrm_smmActivitiesDS_Extension
{
}

Method.Source:
public void initValue()
{
    Args                            locArgs;
    Object                          callerObject;
    FormRun                         formRunCaller;
    Common                          callerRecord;

    smmActivities                   locsmmActivities;
    KCS_KBVBuildingProjectTable     locKCS_KBVBuildingProjectTable;
    date                            dateToday;

    next initValue();

    callerObject    = element.args().caller();

    if (callerObject)
    {
        locArgs         = element.args();
        formRunCaller   = locArgs.caller();

        if(callerObject.name() == formStr(AVAKBVBuildingProjectTable))
        {
            callerRecord        = locArgs.record();
            if(callerRecord.TableId == tableNum(KCS_KBVBuildingProjectTable))
            {
                locKCS_KBVBuildingProjectTable  = callerRecord;
                if(locKCS_KBVBuildingProjectTable.RecId)
                {
                    element.frmKCS_KBVBuildingProjectID = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

                    locsmmActivities    = element.smmActivities;
                    dateToday           = AVAKBVBuildingProjectHelper::getToday();
                    locsmmActivities.setEndDate(dateToday);

                    locsmmActivities.avaSetEndDateTimeFromBP(locKCS_KBVBuildingProjectTable);

                    if (locArgs.menuItemType() == MenuItemType::Display)
                    {
                        if(locArgs.menuitemName() == menuItemDisplayStr(smmActivities))
                        {
                            locsmmActivities.Category   = smmActivityCategory::Action;
                        }
                    }
                }
            }
        }
    }
}

void write()
{
    smmActivities               locsmmActivities;
    smmActivityNumber           locsmmActivityNumber;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;
    KCS_KBVActivitiesForBP      locKCS_KBVActivitiesForBP;



    boolean                     newRecord;
    Common                      common;
    FormRun                     formRunCaller;
    Args                        locArgs;
    Object                      parent;

    Common                      callerRecord;


    locsmmActivities        = element.smmActivities;

    locsmmActivityNumber    = locsmmActivities.ActivityNumber;
    newRecord               = locsmmActivities.RecId == 0;

    next write();

    parent                  = element.args().caller();
    if (parent)
    {
        locArgs             = element.args();
        formRunCaller       = locArgs.caller();
        common              = locArgs.record();

        if (formRunCaller)
        {
            callerRecord    = common;
        }
    }

    if (callerRecord && newRecord)
    {
        if(callerRecord.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = callerRecord;

            if (!KCS_KBVActivitiesForBP::exist(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, locsmmActivityNumber))
            {
                KCS_KBVActivitiesForBP::createReference(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, locsmmActivityNumber);
            }

            /*locKCS_KBVActivitiesForBP.clear();
            locKCS_KBVActivitiesForBP.initValue();
            locKCS_KBVActivitiesForBP.KCS_KBVBuildingProjectID  = locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;
            locKCS_KBVActivitiesForBP.smmActivityNumber         = locsmmActivityNumber;

            locKCS_KBVActivitiesForBP.insert(); */
        }

        if (formRunCaller)
        {
            if(formRunCaller.name() == formStr(AVAKBVBuildingProjectTable))
            {
                formRunCaller.parmCreateKCS_KBVActivitiesForBPOK (true);
                formRunCaller.parmKCS_KBVActivitiesForBPCreated(locKCS_KBVActivitiesForBP);
            }
            if (formHasMethod(formRunCaller, literalStr(afterKCS_KBVActivitiesForBPCreation)))
            {
                formRunCaller.afterKCS_KBVActivitiesForBPCreation();
            }
        }
    }
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Args                    locArgs;

    Query                   locQuery;
    QueryBuildDataSource    locQbds;
    QueryBuildDataSource    locQbdsBase;
    QueryBuildRange         locQbr;
    str                     queryCondition;

    if(element.args())
    {
        locArgs = new Args();
        locArgs = element.args();
    }

    next init();

    locQuery = this.query();

    switch (locArgs.menuitemName())
    {
        case menuItemDisplayStr(AVAKBVActivitiesForBPTileDisplay):
        case menuItemDisplayStr(AVAKBVActivitiesForBPDueTileDisplay):
            locQbdsBase = locQuery.dataSourceTable(tableNum(smmActivities));
            locQbds     = locQuery.dataSourceTable(tableNum(AVAKBVsmmActivitiesMyDueHCMWorkerView));
            locQbds.joinMode(JoinMode::ExistsJoin);
            locQbds.addLink(fieldNum (smmActivities, ActivityNumber),
                            fieldNum (AVAKBVsmmActivitiesMyDueHCMWorkerView, ActivityNumber),
                            locQbdsBase.name()                                                  );
            SysQuery::findOrCreateRange(locQbds, fieldNum (AVAKBVsmmActivitiesMyDueHCMWorkerView, HCMWorker)).value(queryValue(HcmWorkerLookup::currentWorker()));
            break;

    }
}
